The product will be delivered. That is the Mafia promise. And to deliver, we must *verify*. Here is the test suite that ensures our checkout operation runs with the precision of a well-managed franchise.

```typescript
// Checkout.test.tsx
import { render, screen, within } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { Checkout } from './Checkout';
import { CartProvider } from './CartContext';
import { PaymentProvider } from './PaymentContext';

// Arrange - our organization's test infrastructure
const mockProcessPayment = vi.fn();
const mockClearCart = vi.fn();

const mockCartItems = [
  { id: '1', name: 'Protection Services', price: 99.99 },
  { id: '2', name: 'Consulting Fee', price: 149.99 }
];

const renderCheckout = (cartItems = mockCartItems) => {
  return render(
    <CartProvider value={{ items: cartItems, total: 249.98, clearCart: mockClearCart }}>
      <PaymentProvider value={{ processPayment: mockProcessPayment }}>
        <Checkout onComplete={vi.fn()} onCancel={vi.fn()} />
      </PaymentProvider>
    </CartProvider>
  );
};

describe('Checkout - Happy Path', () => {
  it('completes full checkout flow from shipping to confirmation', async () => {
    const user = userEvent.setup();
    mockProcessPayment.mockResolvedValue({ orderId: 'ORD-12345' });
    renderCheckout();

    // Shipping step
    await user.type(screen.getByLabelText(/street address/i), '123 Family Business Ave');
    await user.type(screen.getByLabelText(/city/i), 'Chicago');
    await user.selectOptions(screen.getByLabelText(/state/i), 'CA');
    await user.type(screen.getByLabelText(/zip code/i), '90210');
    await user.click(screen.getByRole('button', { name: /continue to payment/i }));

    // Payment step
    await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
    await user.type(screen.getByLabelText(/expiry/i), '12/25');
    await user.type(screen.getByLabelText(/cvv/i), '123');
    await user.type(screen.getByLabelText(/name on card/i), 'Uncle Enzo');
    await user.click(screen.getByRole('button', { name: /review order/i }));

    // Review step
    expect(screen.getByText(/protection services/i)).toBeInTheDocument();
    await user.click(screen.getByRole('button', { name: /place order/i }));

    // Confirmation
    expect(await screen.findByText(/order confirmed/i)).toBeInTheDocument();
    expect(screen.getByText('ORD-12345')).toBeInTheDocument();
  });
});

describe('Checkout - Form Validation', () => {
  it('displays error when ZIP code format is invalid', async () => {
    const user = userEvent.setup();
    renderCheckout();

    await user.type(screen.getByLabelText(/zip code/i), 'BADZIP');
    await user.click(screen.getByRole('button', { name: /continue to payment/i }));

    expect(screen.getByRole('alert')).toHaveTextContent(/valid zip code required/i);
    expect(screen.getByLabelText(/zip code/i)).toHaveAttribute('aria-invalid', 'true');
  });
});

describe('Checkout - Edge Cases', () => {
  it('shows empty cart message when no items present', () => {
    renderCheckout([]);
    expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
  });

  it('handles payment failure with retry capability', async () => {
    const user = userEvent.setup();
    mockProcessPayment.mockRejectedValueOnce(new Error('Card declined'));
    // ... navigate to review, click place order
    expect(await screen.findByRole('alert')).toHaveTextContent(/card declined/i);
    expect(screen.getByRole('button', { name: /place order/i })).not.toBeDisabled();
  });
});
```

